{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C05", "C24", "C33", "C40", "C01", "C10", "C18", "C15", "C28", "C29", "C173", "C183", "C178"],
  "contradictory_card_ids": ["C32", "C38", "C47", "C56", "C57"],
  "prediction_basis_card_ids": ["C05", "C24", "C33", "C40", "C01", "C10", "C18", "C15", "C28", "C29", "C173", "C183", "C178"],
  "claims": [
    {
      "claim": "Lefamulin, a complex diterpenoid, has absolute oral bioavailability of 25.8% in fasted healthy adults after a 600 mg IR tablet versus IV (C05, C24), and population-PK modeling estimates F=0.24 in the fasted state (C33, C40); this directly supports F>=20% for a similarly complex oxygenated diterpenoid.",
      "card_ids": ["C05", "C24", "C33", "C40"]
    },
    {
      "claim": "BMS-275183, a complex taxane diterpenoid with multiple ester/lactone motifs, has approximately 24% absolute oral bioavailability in humans (C01, C10, C18), supporting transfer of a positive F outcome.",
      "card_ids": ["C01", "C10", "C18"]
    },
    {
      "claim": "Tacrolimus, a complex macrocyclic natural product, has about 20% absolute oral bioavailability in fasted humans (C15) and about 25% in transplant recipients (C28, C29); low rat values (C32, C38, C47, C56, C57) are formulation- and species-specific and do not provide affirmative evidence of F<20% for the query.",
      "card_ids": ["C15", "C28", "C29", "C32", "C38", "C47", "C56", "C57"]
    },
    {
      "claim": "L5 bilobalide, a structurally similar tert-butyl polycyclic trilactone, showed high Caco-2 absorptive Papp (4.96 ± 0.12 ×10^-6 cm/s) and secretory Papp (5.31 ± 0.02 ×10^-6 cm/s), with an efflux ratio near 1, indicating good permeability without marked efflux (C173, C183); transport increased at pH 5.0 (C178). This mechanistically supports absorption for the query scaffold.",
      "card_ids": ["C173", "C183", "C178"]
    },
    {
      "claim": "L5 P-gp/BCRP substrate and intestinal-metabolism records for simvastatin, lovastatin, irinotecan, and other molecules (C164, C167, C176, C189, C195, C196, C180, C193) are molecule-specific and do not establish efflux or gut-wall metabolism for the query; no query-specific presystemic-loss measurement exists.",
      "card_ids": ["C164", "C167", "C176", "C189", "C195", "C196", "C180", "C193"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C173", "C183", "C178"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule; prediction relies on structural analogy to lefamulin, BMS-275183, tacrolimus, and bilobalide rather than an exact match.",
    "No query-specific gut-wall efflux or intestinal-metabolism experiment is available; L5 substrate statuses for P-gp/BCRP and esterase metabolism are for other molecules and cannot be assumed for the query.",
    "Bilobalide is a close but not identical analog; the query has an additional methyl and different hydroxyl/lactone arrangement, so Caco-2 permeability transfer is imperfect.",
    "No formulation-, dose-, or species-specific oral data are available for the query; oral bioavailability can be formulation-dependent.",
    "The physicochemical prior (low logD, high TPSA) suggests a permeability liability, but bilobalide Caco-2 data indicate that this rigid trilactone scaffold can still be well absorbed."
  ],
  "decision_summary": "L5 gut-wall efflux/intestinal-metabolism records do not provide query-specific negative evidence; the closest structural analog, bilobalide, shows high Caco-2 permeability with no marked efflux (C173, C183, C178), which supports absorption. Combined with lefamulin F≈25.8% (C05, C24), BMS-275183 F≈24% (C01, C10, C18), and tacrolimus F≈20-25% in humans (C15, C28, C29), the prediction remains high with moderate confidence."
}

